public interface Shape {
    double area();

    static Shape of(String kind, double a) {      // static factory method
        switch (kind) {
            case "circle": return new Circle(a);
            case "square": return new Square(a);
            default: throw new IllegalArgumentException("unknown shape: " + kind);
        }
    }
}

private final Map<String, Supplier<Shape>> creators = Map.of(
        "circle", () -> new Circle(1.0),
        "square", () -> new Square(2.0));

Shape make(String kind) {
    Supplier<Shape> creator = creators.get(kind);
    if (creator == null) throw new IllegalArgumentException("unknown shape: " + kind);
    return creator.get();
}

public interface PaymentServiceProvider {   // the provider is a factory for the service
